package com.example.takura.media;
import static org.assertj.core.api.Assertions.assertThat;import com.example.takura.media.infrastructure.S3ObjectStorageAdapter;import com.fasterxml.jackson.databind.ObjectMapper;import java.io.ByteArrayOutputStream;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import software.amazon.awssdk.auth.credentials.*;import software.amazon.awssdk.http.urlconnection.UrlConnectionHttpClient;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.*;import software.amazon.awssdk.services.s3.presigner.S3Presigner;
class S3ObjectStorageIntegrationTest {private static final URI ENDPOINT=URI.create("http://127.0.0.1:19000");
 @Test void pinsExactVersionEvenAfterStagingOverwrite()throws Exception{try(var socket=new Socket()){socket.connect(new InetSocketAddress("127.0.0.1",19000),500);}catch(Exception absent){Assumptions.abort("Local S3 emulator is unavailable");}var credentials=StaticCredentialsProvider.create(AwsBasicCredentials.create("test","test"));var config=S3Configuration.builder().pathStyleAccessEnabled(true).build();try(S3Client s3=S3Client.builder().endpointOverride(ENDPOINT).region(Region.AF_SOUTH_1).credentialsProvider(credentials).serviceConfiguration(config).httpClientBuilder(UrlConnectionHttpClient.builder()).build();S3Presigner presigner=S3Presigner.builder().endpointOverride(ENDPOINT).region(Region.AF_SOUTH_1).credentialsProvider(credentials).serviceConfiguration(config).build()){var storage=new S3ObjectStorageAdapter(s3,presigner,credentials,new ObjectMapper(),Clock.systemUTC(),"af-south-1","takura-quarantine-local","takura-private-clean-local","takura-public-derivatives-local",ENDPOINT);String key="quarantine/test/"+UUID.randomUUID();byte[] original="synthetic-original".getBytes(StandardCharsets.UTF_8),replacement="synthetic-replacement".getBytes(StandardCharsets.UTF_8);upload(storage,key,original,"one");var first=storage.headStaging(key);var pinned=storage.pinToPrivate(key,first.version(),"private/test/"+UUID.randomUUID());upload(storage,key,replacement,"two");assertThat(storage.readPrivate(pinned.key(),pinned.version())).isEqualTo(original);assertThat(storage.privateExists(pinned.key(),pinned.version())).isTrue();}}
 private static void upload(S3ObjectStorageAdapter storage,String key,byte[] bytes,String attachment)throws Exception{String checksum=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));var post=storage.createUploadPost(key,bytes.length,"text/plain",checksum,attachment,Duration.ofMinutes(5));String boundary="takura"+UUID.randomUUID().toString().replace("-","");var body=new ByteArrayOutputStream();for(var field:post.fields().entrySet()){part(body,boundary,field.getKey(),field.getValue().getBytes(StandardCharsets.UTF_8),null);}part(body,boundary,"file",bytes,"fixture.txt");body.write(("--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));var connection=(HttpURLConnection)post.url().toURL().openConnection();connection.setRequestMethod("POST");connection.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);connection.setDoOutput(true);connection.getOutputStream().write(body.toByteArray());int status=connection.getResponseCode();String response=status<400?"":new String(connection.getErrorStream().readAllBytes(),StandardCharsets.UTF_8);assertThat(status).withFailMessage(response).isBetween(200,299);}
 private static void part(ByteArrayOutputStream out,String boundary,String name,byte[] value,String file)throws Exception{out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+name+"\""+(file==null?"":"; filename=\""+file+"\"")+"\r\n"+(file==null?"":"Content-Type: text/plain\r\n")+"\r\n").getBytes(StandardCharsets.UTF_8));out.write(value);out.write("\r\n".getBytes(StandardCharsets.UTF_8));}
}
